namespace OpenTribes.Game;

/// <summary>The definition of one datablock field.</summary>
/// <remarks>Port of src/game/datablocks.hpp FieldDef. The tables are generated by tools/gen_datablocks.py from docs/datablocks.md (31 classes in groups 0 to 30).</remarks>
public sealed class FieldDef
{
    /// <summary>The field name.</summary>
    /// <summary>The class name.</summary>
    public readonly string Name;
    /// <summary>The field type code.</summary>
    public readonly int Type;
    /// <summary>The number of array elements.</summary>
    public readonly int Count;
    /// <summary>The text a script read prints on a fresh block. <c>@index0</c> means the first block of the reference group (RF4).</summary>
    public readonly string DefaultText; // as a script read prints it on a fresh block; "@index0" = RF4
    /// <summary>True when no constructor writes the field. It is zero-filled here (D11).</summary>
    public readonly bool Uninit;

    /// <summary>Creates a field definition.</summary>
    /// <param name="name">The field name.</param>
    /// <param name="type">The field type code.</param>
    /// <param name="count">The number of array elements.</param>
    /// <param name="defaultText">The default text.</param>
    /// <param name="uninit">True when no constructor writes the field.</param>
    public FieldDef(string name, int type, int count, string defaultText, bool uninit)
    {
        Name = name;
        Type = type;
        Count = count;
        DefaultText = defaultText;
        Uninit = uninit;
    }
}

/// <summary>The definition of one datablock class.</summary>
/// <remarks>Port of src/game/datablocks.hpp ClassDef.</remarks>
public sealed class ClassDef
{
    /// <summary>The class name.</summary>
    public readonly string Name;
    /// <summary>The datablock group, 0 to 30. Negative for classes without a group.</summary>
    public readonly int Group;
    /// <summary>The parent class name, or null.</summary>
    public readonly string? Parent;
    /// <summary>The fields this class adds to its parent's.</summary>
    public readonly FieldDef[] Fields;
    /// <summary>False when the original crashes on declaration (D11), so the class cannot be declared.</summary>
    public readonly bool Creatable;

    /// <summary>Creates a class definition.</summary>
    /// <param name="name">The class name.</param>
    /// <param name="group">The datablock group.</param>
    /// <param name="parent">The parent class name, or null.</param>
    /// <param name="fields">The fields the class adds.</param>
    /// <param name="creatable">False when the class cannot be declared.</param>
    public ClassDef(string name, int group, string? parent, FieldDef[] fields, bool creatable)
    {
        Name = name;
        Group = group;
        Parent = parent;
        Fields = fields;
        Creatable = creatable;
    }
}

